DELIMITER $$
--
-- Procedures
--
CREATE DEFINER=`root`@`localhost` PROCEDURE `GenerateDataPenjualanArkadia` (IN `jumlah_transaksi` INT)   BEGIN
    DECLARE i INT DEFAULT 1;
    DECLARE v_id_user BIGINT;
    DECLARE v_id_laptop BIGINT;
    DECLARE v_qty INT;
    DECLARE v_harga DECIMAL(15,2);
    DECLARE v_subtotal DECIMAL(15,2);
    DECLARE v_tanggal DATE;
    DECLARE v_invoice VARCHAR(255);
    DECLARE v_metode VARCHAR(50);
    DECLARE v_status VARCHAR(50);
    DECLARE v_id_penjualan BIGINT;
    DECLARE v_created_at TIMESTAMP;

    WHILE i <= jumlah_transaksi DO
        -- 1. Pilih user secara acak (id_user yang tersedia: 1, 2, atau 3)
        SET v_id_user = FLOOR(1 + RAND() * 3);
        
        -- 2. Pilih laptop secara acak (id laptop yang tersedia: 1 sampai 7)
        SET v_id_laptop = FLOOR(1 + RAND() * 7);
        
        -- 3. Ambil harga laptop terpilih secara otomatis
        SELECT harga INTO v_harga FROM laptops WHERE id = v_id_laptop;
        
        -- 4. Tentukan jumlah beli acak (1 sampai 3 unit)
        SET v_qty = FLOOR(1 + RAND() * 3);
        SET v_subtotal = v_harga * v_qty;
        
        -- 5. Tentukan tanggal acak dalam rentang 365 hari terakhir beserta jam acak
        SET v_tanggal = DATE(DATE_SUB(NOW(), INTERVAL FLOOR(RAND() * 365) DAY));
        SET v_created_at = CAST(CONCAT(v_tanggal, ' ', LPAD(FLOOR(RAND()*24),2,'0'), ':', LPAD(FLOOR(RAND()*60),2,'0'), ':', LPAD(FLOOR(RAND()*60),2,'0')) AS DATETIME);
        
        -- 6. Generate nomor invoice unik
        SET v_invoice = CONCAT('INV-', DATE_FORMAT(v_tanggal, '%Y%m%d'), '-', LPAD(i, 6, '0'));
        
        -- 7. Variasi metode pembayaran & status (90% dibuat SUCCESS agar data analitiknya bagus)
        SET v_metode = ELT(FLOOR(1 + RAND() * 4), 'MIDTRANS', 'TRANSFER BANK', 'CASH', 'QRIS');
        SET v_status = IF(RAND() < 0.9, 'SUCCESS', 'PENDING');
        
        -- 8. Masukkan ke tabel induk: penjualan
        VALUES (v_id_user, v_invoice, v_subtotal, v_status, v_tanggal, v_metode, NULL, v_created_at, v_created_at);
        
        -- 9. Ambil ID penjualan terakhir
        SET v_id_penjualan = LAST_INSERT_ID();
        
        -- 10. Masukkan ke tabel anak dengan menyertakan harga_jual dan harga_modal (diset 80% dari harga jual sebagai simulasi)
        VALUES (v_id_penjualan, v_id_laptop, v_qty, v_harga, (v_harga * 0.80), v_subtotal, v_created_at, v_created_at);
        
        SET i = i + 1;
    END WHILE;
END$$

DELIMITER ;

